# The two white mugs remain on the table, so the full goal is incomplete.
# Return both open arms to their saved starting joints and use the remaining action allowance for the final check.
for index in range(26):
    obs, reward, terminated, truncated, info = step({
        'left_arm_joint_state': home_left,
        'right_arm_joint_state': home_right,
        'left_ee_joint_state': [1],
        'right_ee_joint_state': [1]
    })
    if terminated or truncated or bool(info.get('success', False)):
        break
print('actions', index + 1, 'reward', reward, 'terminated', terminated, 'truncated', truncated, 'info', info)
print('home_errors', np.linalg.norm(np.array(obs['state']['left_arm_joint_state'])-home_left), np.linalg.norm(np.array(obs['state']['right_arm_joint_state'])-home_right))

